      const { data: saved, error: saveErr } = await supabase.from("wallets").insert({ user_id: user.userId, circle_wallet_id: wallet.id, circle_wallet_set_id: walletSetId, address: wallet.address, blockchain: BLOCKCHAIN, status: wallet.state ?? "LIVE" }).select().single();
